#[test]
fn test_sum() {
    fn noop(_: *const ()) {}
    fn clone(p: *const ()) -> std::task::RawWaker { std::task::RawWaker::new(p, &VTABLE) }
    static VTABLE: std::task::RawWakerVTable = std::task::RawWakerVTable::new(clone, noop, noop, noop);
    let waker = unsafe { std::task::Waker::from_raw(std::task::RawWaker::new(std::ptr::null(), &VTABLE)) };
    let mut cx = std::task::Context::from_waker(&waker);
    let mut fut = std::pin::pin!(sum_bytes(Data(vec![1, 2, 3])));
    if let std::task::Poll::Ready(res) = fut.as_mut().poll(&mut cx) {
        assert_eq!(res, 6);
    } else {
        panic!("future not ready");
    }
}
